// Define a parameter (created in Manage Parameters UI)
ServerName = "dev-sql-server"  // Type: Text

// Use the parameter in a Source step
Source = Sql.Database(ServerName, "SalesDB")

// Fill Down — for repeated category labels
#"Filled Down" = Table.FillDown(Source, {"Category"}),

// Replace null with 0 — for numeric measures
#"Replaced Nulls" = Table.ReplaceValue(
    #"Filled Down",
    null, 0,
    Replacer.ReplaceValue, {"SalesAmount"}
)

// Parameter: ServerName = "dev-sql-server"
// Parameter: DatabaseName = "SalesDB_Dev"
// Parameter: RowLimit = 100000

Source = Sql.Database(ServerName, DatabaseName),
Filtered = Table.FirstN(Source, RowLimit)
